normalize_input() {
  local arg passthru flags
  passthru=false

  while [[ $# -gt 0 ]]; do
    arg="$1"
    if [[ $passthru == true ]]; then
      input+=("$arg")
    elif [[ $arg =~ ^(--[a-zA-Z0-9_\-]+)=(.+)$ ]]; then
      input+=("${BASH_REMATCH[1]}")
      input+=("${BASH_REMATCH[2]}")
    elif [[ $arg =~ ^(-[a-zA-Z0-9])=(.+)$ ]]; then
      input+=("${BASH_REMATCH[1]}")
      input+=("${BASH_REMATCH[2]}")
    elif [[ $arg =~ ^-([a-zA-Z0-9][a-zA-Z0-9]+)$ ]]; then
      flags="${BASH_REMATCH[1]}"
      for ((i = 0; i < ${#flags}; i++)); do
        input+=("-${flags:i:1}")
      done
    elif [[ "$arg" == "--" ]]; then
      passthru=true
      input+=("$arg")
    else
      input+=("$arg")
    fi

    shift
  done
}

# Everything needed to bring an environment back, relative to $BASE_DIR.
# Competitor images live in Gitea's container registry, so they are inside data/gitea.
BACKUP_ITEMS=(data config dynamic/docker .env competition.lock)

# Write the given items (relative to $BASE_DIR) into a root-only archive.
# --numeric-owner: keep container uids (mysql 999, gitea 1000, verdaccio 10001) even if the host maps
# those numbers to other names or the backup is restored on another machine
write_archive() {
    local file=$1
    shift
    (umask 077 && tar --numeric-owner -czpf "$file" -C "$BASE_DIR" "$@")
}

# Create a tar.gz of BACKUP_ITEMS in $BACKUP_DIR. Services must be stopped for a consistent MySQL copy.
# Sets LAST_BACKUP_FILE (empty when there was nothing to back up).
create_backup_archive() {
    local label=${1:-manual}
    local items=() item
    LAST_BACKUP_FILE=""

    for item in "${BACKUP_ITEMS[@]}"; do
        [ -e "$BASE_DIR/$item" ] && items+=("$item")
    done

    if [ ! -d "$DATA_DIR" ]; then
        log_warning "No data directory, nothing to back up"
        return 0
    fi

    # Archives contain .env, Gitea and MySQL data: readable by root only
    mkdir -p "$BACKUP_DIR"
    chmod 700 "$BACKUP_DIR"
    LAST_BACKUP_FILE="$BACKUP_DIR/backup-$(date +%Y%m%d-%H%M%S)-$label.tar.gz"

    if ! run_with_spinner "Creating $LAST_BACKUP_FILE..." write_archive "$LAST_BACKUP_FILE" "${items[@]}"; then
        rm -f "$LAST_BACKUP_FILE"
        return 1
    fi
    log_success "Backup created ($(du -h "$LAST_BACKUP_FILE" | cut -f1)): $LAST_BACKUP_FILE"
}

list_backups() {
    echo "Available backups in $BACKUP_DIR:"
    ls -1t "$BACKUP_DIR"/backup-*.tar.gz 2>/dev/null | xargs -r -n1 basename | sed 's/^/  /'
}

# Print the archive path for a file path, a file name in $BACKUP_DIR, or "latest"
resolve_backup() {
    local name=$1
    if [ "$name" = "latest" ]; then
        ls -1t "$BACKUP_DIR"/backup-*.tar.gz 2>/dev/null | head -n1
    elif [ -f "$name" ]; then
        realpath "$name"
    elif [ -f "$BACKUP_DIR/$(basename "$name")" ]; then
        echo "$BACKUP_DIR/$(basename "$name")"
    fi
}

# Remove every container, data, generated file and competitor image.
# With do_backup=true (default), a backup is made once the services are down; if it fails nothing is deleted.
clean_environment() {
    local do_backup=${1:-true}

    load_configuration
    local config_file=$CONFIG_DIR/main.json

    log_section "Cleaning Competition Environment"

    log_subsection "Stopping Docker Services"
    compose_each --reverse down -v
    log_success "Docker services stopped"

    # Services are down at this point, so the copy is consistent
    if [ "$do_backup" = true ]; then
        log_subsection "Backing up before removing anything"
        if ! create_backup_archive "clean"; then
            log_error "Backup failed, nothing was deleted. Use --no-backup to clean anyway."
            exit 1
        fi
    else
        log_warning "Skipping backup (--no-backup)"
    fi

    log_subsection "Removing Data Volumes"
    rm -rf "$DATA_DIR"
    log_success "Data volumes removed"

    log_subsection "Removing Competitor Images"
    local username
    for username in $(jq -r '.competitors[].username' "$config_file"); do
        log_info "Removing images for competitor: $username"
        docker images -q --filter "reference=git.$DOMAIN/$username/*" | xargs -r docker rmi -f
    done
    log_success "Competitor images removed"

    log_subsection "Cleaning up Dynamic Directories"
    rm -rf "$DYNAMIC_DOCKER_DIR"
    rm -rf "$DYNAMIC_FRAMEWORKS_DIR"
    rm -f "$LOCK_FILE"
    log_success "Dynamic directories cleaned"

    echo ""
    log_success "Clean complete! Environment reset. 🧹"
}

# Initialize competitors configuration files
initialize_competitors_config() {
    log_info "Initializing competitors configuration..."

    cat <<EOF > $DYNAMIC_DOCKER_DIR/competitors.yaml
services:
EOF

    cat <<EOF > $CONFIG_DIR/mysql/competitors.sql
EOF
}

# Add competitor module to Docker Compose configuration
add_competitor_module_to_compose() {
    local user=$1
    local module=$2
    local subdomain=$3

    cat <<EOF >> $DYNAMIC_DOCKER_DIR/competitors.yaml
  ${user}_${module}:
    image: git.${DOMAIN}/${user}/${module}:1.0.0
    container_name: ${user}_${module}
    restart: always
    networks:
      - gitea
    labels:
      - "wud.watch=true"
      - "wud.watch.digest=true"
      - "wud.registry=gitea.private"
      - 'wud.tag.include=^\d+\.\d+\.\d+\$\$'
      - "traefik.enable=true"
      - "traefik.http.routers.${user}_${module}.rule=Host(\`${subdomain}-${module}.$DOMAIN\`)"
      - "traefik.http.routers.${user}_${module}.entrypoints=${ENTRYPOINT}"
      - "traefik.http.routers.${user}_${module}.tls=${ENABLE_HTTPS}"
      - "traefik.http.services.${user}_${module}.loadbalancer.server.port=80"
EOF
}

# Add competitor module to MySQL configuration
add_competitor_module_to_sql() {
    local user=$1
    local module=$2
    local pass=$3

    cat <<EOF >> $CONFIG_DIR/mysql/competitors.sql
  CREATE DATABASE IF NOT EXISTS \`${user}_${module}\`;
  CREATE USER IF NOT EXISTS '$user'@'%' IDENTIFIED BY '$pass';
  GRANT ALL PRIVILEGES ON \`${user}_${module}\`.* TO '$user'@'%';
EOF
}

# Push initial container image for competitor module
push_initial_module_image() {
    local user=$1
    local module=$2

    log_debug "Pushing initial container for $user/$module"
    docker tag nginx:latest git.$DOMAIN/$user/$module:1.0.0
    docker tag nginx:latest git.$DOMAIN/$user/$module:latest

    run_with_spinner "Pushing initial image for $user/$module..." \
        docker push --all-tags git.$DOMAIN/$user/$module
}

# Process a single competitor module
process_competitor_module() {
    local user=$1
    local module=$2
    local subdomain=$3
    local pass=$4

    log_debug "Processing module: $module for $user"

    add_competitor_module_to_compose "$user" "$module" "$subdomain"
    add_competitor_module_to_sql "$user" "$module" "$pass"
    push_initial_module_image "$user" "$module"
}

# Process a single competitor
process_competitor() {
    local config_row=$1

    _jq() {
        echo ${config_row} | base64 --decode | jq -r ${1}
    }

    local username=$(_jq '.username')
    local password=$(_jq '.password')
    local subdomain=$(_jq '.subdomain')

    log_subsection "Competitor: $(_jq '.name')"
    log_info "Creating Gitea user: $username (subdomain: $subdomain)"

    create_competitor_user "$username" "$password"
    add_competitor_to_team "frameworks" "competitors" "$username"
    create_user_secrets "$username" "$password"

    for module in $MODULES; do
        process_competitor_module "$username" "$module" "$subdomain" "$password"
    done
}

# Process all competitors from configuration file
process_all_competitors() {
    local config_file=$1

    log_section "Processing All Competitors"

    for row in $(jq -r '.competitors[] | @base64' "$config_file"); do
        process_competitor "$row"
    done
}

# Finalize Docker Compose configuration
finalize_docker_compose_config() {
    cat <<EOF >> $DYNAMIC_DOCKER_DIR/competitors.yaml

networks:
  gitea:
    external: true
EOF
}

# Load and export configuration from main.json
load_configuration() {
    local config_file=$CONFIG_DIR/main.json
    log_debug "Loading configuration from $config_file"

    export DOMAIN=$(jq -r '.domain' "$config_file")
    export ENABLE_HTTPS=$(jq -r '.enable_https' "$config_file")
    export USERNAME=$(jq -r '.username' "$config_file")
    export PASSWORD=$(jq -r '.password' "$config_file")
    export MODULES=$(jq -r '.modules | join(" ")' "$config_file")
    export FRAMEWORKS_REPO=$(jq -r '.frameworks.frameworks_repo' "$config_file")
    export ALLOWED_FRAMEWORKS=$(jq -r '.frameworks.allowed_frameworks | join(" ")' "$config_file")
}

# Setup HTTP/HTTPS related variables
setup_protocol_vars() {
    if [ "$ENABLE_HTTPS" = "true" ]; then
        export ENTRYPOINT=websecure
        export GITEA_PROTOCOL=https
        export REGISTRY_PORT=443
    else
        export ENTRYPOINT=web
        export GITEA_PROTOCOL=http
        export REGISTRY_PORT=5000
    fi
}

# Setup service hostnames and credentials
setup_service_vars() {
    export GITEA_HOSTNAME=$DOMAIN
    export MYSQL_ROOT_PASSWORD=$PASSWORD
    export GITEA_URL="$GITEA_PROTOCOL://git.$DOMAIN"
}

# Setup directory variables
setup_directory_vars() {
    mkdir -p ${DYNAMIC_DOCKER_DIR} ${DYNAMIC_FRAMEWORKS_DIR}
    export CONFIG_FILE=$CONFIG_DIR/main.json
}

# Initialize lock file
create_lock_file() {
    touch $LOCK_FILE
}

# Main configuration initialization
initialize_configuration() {
    log_section "Initializing Configuration"
    load_configuration
    log_debug "Loaded configuration from main.json"
    setup_protocol_vars
    log_debug "Setup protocol variables (HTTPS: $ENABLE_HTTPS)"
    setup_service_vars
    log_debug "Setup service variables"
    setup_directory_vars
    log_debug "Setup directory variables"
    create_lock_file
    log_success "Configuration initialized"
}

# Start a Docker Compose service
docker_compose() {
    local file="$1"
    log_info "Starting service from $file"
    docker compose -f $DOCKER_DIR/${file} up -d

}

# Poll Gitea until it answers, returns 1 after the last retry
poll_gitea() {
    local retries=10
    local wait=5
    local count=0

    until curl -s http://localhost:3000/api/v1/version > /dev/null; do
        if [ $count -ge $retries ]; then
            return 1
        fi
        log_debug "Gitea health check attempt $((count + 1))/$retries"
        sleep $wait
        count=$((count + 1))
    done
}

# Wait for Gitea to be ready
wait_for_gitea() {
    if ! run_with_spinner "Waiting for Gitea to be ready..." poll_gitea; then
        log_error "Gitea did not become ready in time."
        exit 1
    fi
    log_success "Gitea is ready"
}

