}

# Bashly filters: printing a message stops the command with that error

# Data files belong to container users (root, mysql 999, gitea 1000, verdaccio 10001), so every command
# runs as root: init creates them, backup/clean read them, restore gives them back their owners.
filter_root() {
    [ "$EUID" -eq 0 ] || echo "This command must be run as root: sudo $0 ..."
}

filter_initialized() {
    [ -f "$LOCK_FILE" ] || echo "Competition is not initialized. Please run the 'init' command first."
}

filter_not_initialized() {
    [ ! -f "$LOCK_FILE" ] || echo "Competition is already initialized. To re-initialize, please run the 'clean' command first."
}

# Import a framework from a local path
import_framework() {
    local framework_path=$1
    local framework_name=$2

    # Check if .npmrc exists and replace ##DOMAIN## with actual domain
    if [ -f "$framework_path/.npmrc" ]; then
        log_info "Found .npmrc in $framework_name, replacing ##DOMAIN## with $DOMAIN"
        sed -i "s/##DOMAIN##/$DOMAIN/g" "$framework_path/.npmrc"
        log_info ".npmrc updated with domain: $DOMAIN"
    fi

    push_framework_repo "$framework_path" "$framework_name"
}

# Create (or update) the template repository <name> in the "frameworks" organization from a local folder.
# Runs in a subshell: it changes directory and may exit early.
push_framework_repo() (
    local repo_path=$1
    local repo_name=$2
    local org_name='frameworks'
    local host="git.${DOMAIN}"
    local remote_url="https://$USERNAME:$PASSWORD@$host/$org_name/$repo_name.git"

    cd "$repo_path" || exit 1

    local repo_status
    repo_status=$(curl -s -k -o /dev/null -w '%{http_code}' -H "Authorization: token $GITEA_TOKEN" "https://$host/api/v1/repos/$org_name/$repo_name")

    if [ "$repo_status" = "200" ]; then
        # The template already exists: commit the new content on top of its history instead of recreating it,
        # so repositories generated from it keep their link and nothing is force-pushed.
        echo "Repository $repo_name already exists, updating it..."
        rm -rf .git
        local tmp_clone
        tmp_clone=$(mktemp -d)
        if ! git -c http.sslVerify=false clone --quiet --no-checkout "$remote_url" "$tmp_clone" > $REDIRECT 2>&1; then
            rm -rf "$tmp_clone"
            echo "Failed to clone $org_name/$repo_name from Gitea"
            exit 1
        fi
        mv "$tmp_clone/.git" .git
        rm -rf "$tmp_clone"
        git config user.name "Init Bot"
        git config user.email "iniot@skill17.com"
        git config http.sslVerify false

        git add -A
        if git diff --cached --quiet; then
            echo "Repository $repo_name is already up to date."
            exit 0
        fi
        git commit -m "Update framework" > $REDIRECT 2>&1
        git push origin HEAD > $REDIRECT 2>&1 || {
            echo "Failed to push $repo_name to Gitea"
            exit 1
        }
        echo "Repository $repo_name updated in the $org_name organization !"
        exit 0
    fi

    echo "Configuring git repository..."
    git init -b main > $REDIRECT 2>&1
    git config user.name "Init Bot"
    git config user.email "iniot@skill17.com"
    git config http.sslVerify false

    echo "Commiting changes..."
    git add -A
    git commit -m "Initial commit" > $REDIRECT 2>&1

    echo "Creating the repository on Gitea"
    local create_repo_response
    create_repo_response=$(curl -s -k -X POST "https://$host/api/v1/orgs/$org_name/repos" \
        -H "Authorization: token $GITEA_TOKEN" \
        -H "Content-Type: application/json" \
        -d '{
          "name": "'"$repo_name"'",
          "private": false,
          "template": true
        }')

    if echo "$create_repo_response" | grep -q '"id":'; then
        echo "Repository $repo_name created in the $org_name organization on Gitea."
    else
        echo "Failed to create repository on Gitea: $create_repo_response"
        exit 1
    fi

    echo "Pushing the repository to Gitea..."
    git remote remove gitea 2>/dev/null
    git remote add gitea "$remote_url"
    git push -u gitea main --force > $REDIRECT 2>&1

    echo "Repository $repo_name pushed to the $org_name organization !"
)

# Setup Docker credentials for registry
setup_docker_registry_credentials() {
    log_info "Setting up Docker registry credentials..."

    run_with_spinner "Pulling nginx image..." docker pull nginx:latest
    docker login -u $USERNAME -p $PASSWORD git.$DOMAIN > /dev/null 2>&1
    log_success "Docker registry credentials configured"
}

# Clone and process frameworks repository, importing only allowed frameworks
import_all_frameworks() {
    log_section "Importing Frameworks"

    if [ -z "$ALLOWED_FRAMEWORKS" ]; then
        log_warning "No allowed_frameworks configured, importing all frameworks"
    fi

    rm -rf "$DYNAMIC_FRAMEWORKS_DIR"
    run_with_spinner "Cloning frameworks repository..." git clone "$FRAMEWORKS_REPO" "$DYNAMIC_FRAMEWORKS_DIR" || exit 1

    cd "$DYNAMIC_FRAMEWORKS_DIR" || exit 1
    rm -rf "$DYNAMIC_FRAMEWORKS_DIR/.git"

    local imported=() failed=()
    for dir in */; do
        [ -d "$dir" ] || continue
        framework_name=$(basename "$dir")

        # Skip frameworks not in the allow list (exact, case-sensitive match)
        if [ -n "$ALLOWED_FRAMEWORKS" ] && [[ " $ALLOWED_FRAMEWORKS " != *" $framework_name "* ]]; then
            log_info "Skipping $framework_name (not in allowed_frameworks)"
            continue
        fi

        framework_path=$(realpath "$dir")
        log_subsection "Framework: $framework_name"
        if run_with_spinner "Importing $framework_name..." import_framework "$framework_path" "$framework_name"; then
            log_success "$framework_name imported"
            imported+=("$framework_name")
        else
            failed+=("$framework_name")
        fi
    done

    # Warn about allowed frameworks that don't exist in the repository
    for allowed in $ALLOWED_FRAMEWORKS; do
        [[ " ${imported[*]} ${failed[*]} " == *" $allowed "* ]] || log_warning "Allowed framework '$allowed' not found in repository"
    done

    log_success "Imported ${#imported[@]} framework(s): ${imported[*]}"
    [ ${#failed[@]} -eq 0 ] || log_error "Failed: ${failed[*]}"
    cd - > /dev/null
    [ ${#failed[@]} -eq 0 ]
}

# Create admin user in Gitea
create_admin_user() {
    local username=$1
    local password=$2

    log_info "Creating Gitea admin user: $username"
    docker exec gitea su -c "/app/gitea/gitea admin user create --username $username --password $password --email $username@example.com --admin" git
}

# Generate registration token for Gitea runner
generate_registration_token() {
    log_info "Generating registration token for Gitea runner..."
    local token=$(docker exec gitea su -c '/app/gitea/gitea actions generate-runner-token' git)
    export REGISTRATION_TOKEN=$token
    log_success "Registration Token: $REGISTRATION_TOKEN"
}

# Create organization in Gitea
create_organization() {
    local org_name=$1

    log_info "Creating organization: $org_name"
    curl -s -k -X POST "$GITEA_URL/api/v1/orgs" \
        -H "Content-Type: application/json" \
        -H "Authorization: token $GITEA_TOKEN" \
        -d "{
            \"username\": \"$org_name\",
            \"full_name\": \"$org_name\"
        }" > /dev/null
}

# Create a personal access token for the admin and print it. Gitea refuses two tokens with the same name.
create_pat() {
    local token_name=${1:-CreateOrganizationScript}
    local response new_token

    response=$(curl -s -k -X POST -H "Content-Type: application/json" \
        -u "$USERNAME:$PASSWORD" \
        -d '{
              "name": "'"$token_name"'",
              "scopes": ["read:admin","write:organization,write:repository,write:user"]
            }' \
        "$GITEA_URL/api/v1/users/$USERNAME/tokens")

    new_token=$(echo "$response" | grep -o '"sha1":"[^"]*"' | sed 's/"sha1":"//;s/"//g')
    if [ -z "$new_token" ] || [ "$new_token" == "null" ]; then
        echo "Failed to create token. Response: $response"
        return 1
    fi
    echo "$new_token"
}

# Get or create PAT token
get_personal_access_token() {
    export GITEA_TOKEN=$(create_pat)
}

# Returns 0 if $GITEA_TOKEN is accepted by Gitea
gitea_token_is_valid() {
    [ -n "$GITEA_TOKEN" ] || return 1
    [ "$(curl -s -k -o /dev/null -w '%{http_code}' -H "Authorization: token $GITEA_TOKEN" "$GITEA_URL/api/v1/user")" = "200" ]
}

# Use the token stored in .env by init. Installations made before it was stored get a new one,
# under a unique name (Gitea refuses duplicate names), saved to .env so this only happens once.
load_personal_access_token() {
    local env_file=$1
    gitea_token_is_valid && return 0

    log_warning "No valid GITEA_TOKEN in $env_file, creating a new one"
    export GITEA_TOKEN=$(create_pat "competition-scripts-$(date +%Y%m%d%H%M%S)")
    if ! gitea_token_is_valid; then
        log_error "Could not get a Gitea access token: $GITEA_TOKEN"
        return 1
    fi
    sed -i '/^GITEA_TOKEN=/d' "$env_file"
    echo "GITEA_TOKEN=\"$GITEA_TOKEN\"" >> "$env_file"
    log_success "Token saved to $env_file"
}

# Create user-level action secret
create_user_secret() {
    local user=$1
    local pass=$2
    local secret_name=$3
    local secret_value=$4

    curl -s -k -X PUT \
        -u "$user:$pass" \
        -H "Content-Type: application/json" \
        -d "{\"data\": \"$secret_value\"}" \
        "$GITEA_URL/api/v1/user/actions/secrets/$secret_name" > /dev/null
}

# Create all standard secrets for a user
create_user_secrets() {
    local user=$1
    local pass=$2

    log_info "Creating user-level secrets for $user..."

    create_user_secret "$user" "$pass" "USER" "$user"
    create_user_secret "$user" "$pass" "PASS" "$pass"
    create_user_secret "$user" "$pass" "DOMAIN" "$DOMAIN"
    create_user_secret "$user" "$pass" "NPM_REGISTRY_URL" "http://verdaccio:4873"
    create_user_secret "$user" "$pass" "SERVER_IP" "127.0.0.1"
}

# Create competitor user in Gitea
create_competitor_user() {
    local username=$1
    local password=$2

    log_info "Creating Gitea user: $username"
    docker exec gitea su -c "/app/gitea/gitea admin user create --username '$username' --password '$password' --email '$username@example.com' --must-change-password=false" git
}

# Add user to team
add_competitor_to_team() {
    local org=$1
    local team=$2
    local user=$3

    local team_id response

    team_id=$(curl -k -s -H "Authorization: token $GITEA_TOKEN" "$GITEA_URL/api/v1/orgs/$org/teams/search?q=$team" \
        | awk -F'"id":' '{print $2}' | awk -F',' '{print $1}' | head -n 1)
    if [ -z "$team_id" ] || [ "$team_id" == "null" ]; then
        log_error "Failed to retrieve team ID for team '$team' in organization '$org'."
        return 1
    fi

    response=$(curl -k -s -o /dev/null -w "%{http_code}" -X PUT \
        -H "Content-Type: application/json" \
        -H "Authorization: token $GITEA_TOKEN" \
        "$GITEA_URL/api/v1/teams/$team_id/members/$user")
    if [ "$response" -ne 204 ]; then
        log_error "Failed to add user '$user' to team '$team' in organization '$org'. HTTP status code: $response"
        return 1
    fi
    log_info "User '$user' added to team '$team' in organization '$org'."
}

# Create a team in an organization
create_team() {
    local org=$1
    local team=$2
    local can_create_org_repo=$3
    local response team_id

    response=$(curl -k -s -X POST -H "Content-Type: application/json" \
        -H "Authorization: token $GITEA_TOKEN" \
        -d '{
              "name": "'"$team"'",
              "can_create_org_repo": '"$can_create_org_repo"',
              "units_map": {
                "repo.actions": "read",
                "repo.packages": "none",
                "repo.code": "write",
                "repo.issues": "write",
                "repo.ext_issues": "none",
                "repo.wiki": "admin",
                "repo.pulls": "owner",
                "repo.releases": "none",
                "repo.projects": "none",
                "repo.ext_wiki": "none"
              }
            }' \
        "$GITEA_URL/api/v1/orgs/$org/teams")

    team_id=$(echo "$response" | awk -F'"id":' '{print $2}' | awk -F',' '{print $1}')
    if [ -z "$team_id" ] || [ "$team_id" == "null" ]; then
        log_error "Failed to create team. Response: $response"
        return 1
    fi
    log_info "Created team '$team' (ID: $team_id)"
}

# Setup basic organizations and teams
setup_organizations_and_teams() {
    log_section "Setting up Organizations and Teams"

    create_organization "images"
    create_organization "frameworks"

    create_team "frameworks" "competitors" false
}

# Color definitions
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
MAGENTA='\033[0;35m'
BOLD='\033[1m'
NC='\033[0m' # No Color

# Log functions
log_info() {
    echo -e "${BLUE}ℹ${NC}  $*"
}

log_success() {
    echo -e "${GREEN}✓${NC}  $*"
}

log_error() {
    echo -e "${RED}✗${NC}  $*" >&2
}

log_warning() {
    echo -e "${YELLOW}⚠${NC}  $*"
}

log_section() {
    echo ""
    echo -e "${BOLD}${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${BOLD}${CYAN}▶  $*${NC}"
    echo -e "${BOLD}${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
}

log_subsection() {
    echo -e "${BOLD}${MAGENTA}→  $*${NC}"
}

log_debug() {
    if [ "$VERBOSE" = true ]; then
        echo -e "${CYAN}🔍  $*${NC}"
    fi
}

# Spinner for long-running operations
show_spinner() {
    local pid=$1
    local message=$2
    local delay=0.1
    local spinner=( '⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏' )

    while kill -0 $pid 2>/dev/null; do
        for i in "${spinner[@]}"; do
            echo -ne "\r${CYAN}$i${NC}  ${message}"
            sleep $delay
        done
    done
    echo -ne "\r\033[K"
}

# Run a command (or function) behind a spinner. Its output is hidden, and printed only if it fails.
# In verbose mode, or when the output is not a terminal, the output is shown directly instead.
run_with_spinner() {
    local message=$1
    shift

    if [ "$VERBOSE" = true ] || [ ! -t 1 ]; then
        log_info "$message"
        "$@"
        return
    fi

    local output pid status
    output=$(mktemp)
    "$@" > "$output" 2>&1 &
    pid=$!
    # Background jobs ignore Ctrl+C in scripts: stop it ourselves
    trap 'kill $pid 2>/dev/null; echo -ne "\r\033[K"; rm -f "$output"; exit 130' INT TERM
    show_spinner $pid "$message"
    wait $pid
    status=$?
    trap - INT TERM

    if [ $status -ne 0 ]; then
        log_error "$message (failed)"
        cat "$output" >&2
    fi
    rm -f "$output"
    return $status
}

# Recreate services individually, without touching the rest of the stack

# Maps "service name" -> "compose file"
declare -gA SERVICE_FILE
# Maps "group name" (compose file basename) -> "compose file"
declare -gA GROUP_FILE

build_service_map() {
    local file group svc
    while read -r file; do
        [ -f "$file" ] || continue
        group=$(basename "$file" .yaml)
        GROUP_FILE[$group]=$file
        for svc in $(docker compose -f "$file" config --services 2>/dev/null < /dev/null); do
            SERVICE_FILE[$svc]=$file
        done
    done < <(compose_files)
    # Friendly aliases
    [ -n "${GROUP_FILE[gitea-runner]}" ] && GROUP_FILE[runners]=${GROUP_FILE[gitea-runner]}
}

print_available() {
    echo "Available services:"
    local file
    while read -r file; do
        [ -f "$file" ] || continue
        echo -n "  $(basename "$file" .yaml): "
        docker compose -f "$file" config --services 2>/dev/null < /dev/null | tr '\n' ' '
        echo ""
    done < <(compose_files)
    echo ""
    echo "A group name (e.g. 'mysql', 'runners', 'competitors') recreates every service of that file."
    echo "An exact service name always takes precedence over a group name (e.g. 'gitea' only recreates the gitea container)."
}

# Remove a container that holds the service's container_name but is no longer tracked by compose
# (e.g. a competitor container redeployed by WUD), otherwise "up" fails with a name conflict.
remove_untracked_container() {
    local file=$1 svc=$2
    local name
    name=$(docker compose -f "$file" config --format json 2>/dev/null | jq -r --arg s "$svc" '.services[$s].container_name // empty')
    [ -n "$name" ] || return 0
    docker container inspect "$name" > /dev/null 2>&1 || return 0
    if [ -z "$(docker compose -f "$file" ps -a -q "$svc" 2>/dev/null)" ]; then
        log_warning "Container '$name' exists but is not tracked by compose, removing it"
        docker rm -f "$name" > /dev/null
    fi
}

recreate_service() {
    local file=$1 svc=$2
    local files=(-f "$file")
    local override=""

    log_subsection "$svc"

    # Competitor images are bumped by WUD after the initial 1.0.0; keep the image currently running
    # instead of rolling the competitor back to the tag written in competitors.yaml.
    if [ "$file" = "$DYNAMIC_DOCKER_DIR/competitors.yaml" ]; then
        local running wanted
        running=$(docker inspect "$svc" --format '{{.Config.Image}}' 2>/dev/null)
        wanted=$(docker compose -f "$file" config --format json | jq -r --arg s "$svc" '.services[$s].image')
        if [ -n "$running" ] && [ "$running" != "$wanted" ]; then
            log_info "Keeping currently deployed image $running (compose file says $wanted)"
            override=$(mktemp --suffix=.yaml)
            printf 'services:\n  %s:\n    image: %s\n' "$svc" "$running" > "$override"
            files+=(-f "$override")
        fi
    fi

    remove_untracked_container "$file" "$svc"
    docker compose "${files[@]}" up -d --no-deps --force-recreate "$svc"
    local status=$?
    [ -n "$override" ] && rm -f "$override"
    return $status
}

# Every compose file of the stack, in start order: traefik creates the "gitea" network the others join,
# and competitor images are pulled from Gitea's registry, so Gitea comes before them.
compose_files() {
    printf '%s\n' \
        "$DOCKER_DIR/traefik.yaml" \
        "$DOCKER_DIR/gitea.yaml" \
        "$DOCKER_DIR/gitea-runner.yaml" \
        "$DOCKER_DIR/mysql.yaml" \
        "$DOCKER_DIR/verdaccio.yaml" \
        "$DOCKER_DIR/wud.yaml" \
        "$DYNAMIC_DOCKER_DIR/competitors.yaml"
}

# Run "docker compose -f <file> <args...>" on every existing compose file.
# --reverse goes from competitors down to traefik (for stop/down).
compose_each() {
    local order=compose_files
    if [ "$1" = "--reverse" ]; then
        order="compose_files_reversed"
        shift
    fi

    local file
    # fd 3: docker compose must not read the file list from stdin
    while read -r file <&3; do
        [ -f "$file" ] || continue
        docker compose -f "$file" "$@"
    done 3< <($order)
}

compose_files_reversed() {
    compose_files | tac
}

# Returns 0 if at least one container of the project is running
project_is_running() {
    [ -n "$(docker ps -q --filter "label=com.docker.compose.project=$COMPOSE_PROJECT_NAME")" ]
}

competition.sh_setup_command() {

  log_section "Installing Dependencies"

  # Detect OS
  if [ -f /etc/os-release ]; then
      . /etc/os-release
      OS=$NAME
      VERSION_CODENAME=${VERSION_CODENAME:-$(echo $VERSION | cut -d' ' -f1)}
  else
      log_error "Cannot detect OS"
      exit 1
  fi

  log_info "Detected OS: $OS"

  # Update package manager
  log_subsection "Updating Package Manager"
  apt update
  log_success "Package manager updated"

  # Install basic dependencies
  log_subsection "Installing Basic Dependencies"
  basic_deps="ca-certificates curl git sudo wget apt-transport-https gnupg lsb-release"
  apt install -y $basic_deps
  log_success "Basic dependencies installed"

  # Install jq for JSON parsing
  log_subsection "Installing jq"
  apt install -y jq
  log_success "jq installed"

  # Install Docker
  log_subsection "Installing Docker"

  # Add Docker's official GPG key
  log_info "Adding Docker GPG key..."
  install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/debian/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  log_debug "Docker GPG key added"

  # Add the repository to Apt sources
  log_info "Adding Docker repository..."
  echo \
    "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/debian \
    $(. /etc/os-release && echo "$VERSION_CODENAME") stable" | \
    tee /etc/apt/sources.list.d/docker.list > /dev/null
  apt update
  log_debug "Docker repository added"

  # Install Docker packages
  log_info "Installing Docker packages..."
  apt install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  log_success "Docker installed"

  # Setup Docker daemon
  log_subsection "Configuring Docker"
  systemctl enable docker
  systemctl start docker
  log_success "Docker daemon configured and started"

  # Add current user to docker group (if not running as root)
  if [ -n "$SUDO_USER" ]; then
      log_info "Adding $SUDO_USER to docker group..."
      usermod -aG docker "$SUDO_USER"
      log_success "$SUDO_USER added to docker group (may require logout/login)"
  fi

  # Install certbot for Let's Encrypt (optional but recommended)
  log_subsection "Installing Certbot (Let's Encrypt)"
  apt install -y certbot python3-certbot-dns-route53 || apt install -y certbot
  log_success "Certbot installed"

  # Install btop for system monitoring (optional but useful)
  log_subsection "Installing System Tools"
  apt install -y btop net-tools
  log_success "System tools installed"

  # Verify installations
  log_section "Verifying Installations"

  check_command() {
      if command -v "$1" &> /dev/null; then
          version=$($1 --version 2>&1 | head -n1)
          log_success "$1 installed: $version"
          return 0
      else
          log_error "$1 not found"
          return 1
      fi
  }

  check_command "docker"
  check_command "jq"
  check_command "git"
  check_command "curl"
  check_command "wget"

  # Verify docker daemon is running
  if docker ps > /dev/null 2>&1; then
      log_success "Docker daemon is running"
  else
      log_warning "Docker daemon may not be running. Try: sudo systemctl start docker"
  fi

  echo ""
  log_success "All dependencies installed successfully! 🎉"
  echo ""
  log_info "Next steps:"
  echo "  1. Review config/main.json and customize settings"
  echo "  2. Run: sudo ./competition.sh init"
  echo ""

}

competition.sh_init_command() {

  # Initialize configuration
  initialize_configuration

  # Start core infrastructure
  start_core_services

  # Wait for Gitea to be ready
  wait_for_gitea

  # Create admin user and setup runner
  log_section "Setting up Admin User and Runner"
  create_admin_user "$USERNAME" "$PASSWORD"
  generate_registration_token
  start_runner_services

  # Setup Gitea access and organizations
  log_section "Setting up Gitea Access"
  get_personal_access_token
  setup_organizations_and_teams

  # Import frameworks
  import_all_frameworks
  setup_docker_registry_credentials

  # Setup competitors
  initialize_competitors_config
  process_all_competitors "$CONFIG_FILE"
  finalize_docker_compose_config

  # Start services
  start_database_services
  start_supporting_services
  configure_verdaccio_permissions
  start_competitor_services

  # Export environment variables
  export_environment_variables "$BASE_DIR/.env"

  echo ""
  log_success "All done! Competition environment is ready! 🎉"

}

competition.sh_start_command() {

  log_section "Starting Services"
  compose_each start
  log_success "Services started"

}

competition.sh_stop_command() {

  log_section "Stopping Services"
  compose_each --reverse stop
  log_success "Services stopped"

}

competition.sh_recreate_command() {

  eval "targets=(${args[service]})"

  build_service_map

  if [ ${#targets[@]} -eq 0 ]; then
      print_available
      exit 0
  fi

  for target in "${targets[@]}"; do
      if [ -z "${SERVICE_FILE[$target]}" ] && [ -z "${GROUP_FILE[$target]}" ]; then
          log_error "Unknown service or group: $target"
          echo ""
          print_available
          exit 1
      fi
  done

  log_section "Recreating Services"
  had_failure=0
  for target in "${targets[@]}"; do
      if [ -n "${SERVICE_FILE[$target]}" ]; then
          recreate_service "${SERVICE_FILE[$target]}" "$target" || had_failure=1
      else
          file=${GROUP_FILE[$target]}
          for svc in $(docker compose -f "$file" config --services); do
              recreate_service "$file" "$svc" || had_failure=1
          done
      fi
  done

  if [ "$had_failure" -ne 0 ]; then
      log_error "Some services failed to be recreated"
      exit 1
  fi
  log_success "Done"

}

competition.sh_import_frameworks_command() {

  # Reads frameworks_repo and allowed_frameworks from config/main.json:
  #   - existing templates get a new "Update framework" commit (history and links from generated repos kept)
  #   - newly allowed frameworks are created
  #   - frameworks removed from allowed_frameworks are left untouched in Gitea
  load_configuration
  setup_protocol_vars
  setup_service_vars
  setup_directory_vars

  wait_for_gitea

  load_personal_access_token "$BASE_DIR/.env" || exit 1

  import_all_frameworks

}

competition.sh_backup_command() {

  # Services are stopped during the copy so the MySQL files are consistent, then started again
  log_section "Backing up Competition Environment"

  was_running=false
  if project_is_running; then
      was_running=true
      log_subsection "Stopping services for a consistent copy"
      compose_each --reverse stop
  fi

  log_subsection "Archiving"
  create_backup_archive "manual"
  status=$?

  if [ "$was_running" = true ]; then
      log_subsection "Starting services again"
      compose_each start
  fi

  exit $status

}

competition.sh_restore_command() {

  # The current environment is cleaned first, which itself creates a backup of it
  if [ -z "${args[backup]}" ]; then
      list_backups
      exit 0
  fi

  archive=$(resolve_backup "${args[backup]}")
  if [ -z "$archive" ]; then
      log_error "Backup not found: ${args[backup]}"
      echo ""
      list_backups
      exit 1
  fi

  log_section "Restoring $(basename "$archive")"

  log_subsection "Checking archive"
  contents=$(tar -tzf "$archive" 2>/dev/null) || { log_error "Archive is corrupted or unreadable"; exit 1; }
  if ! grep -q '^data/' <<< "$contents" || ! grep -qx '.env' <<< "$contents"; then
      log_error "This archive does not look like a competition backup (missing data/ or .env)"
      exit 1
  fi
  log_success "Archive OK"

  clean_environment true

  log_section "Extracting Backup"
  run_with_spinner "Extracting $(basename "$archive")..." \
      tar --numeric-owner -xzpf "$archive" -C "$BASE_DIR" || exit 1

  # .env stores absolute paths; fix them if the project was moved since the backup
  old_base=$(sed -n 's/^BASE_DIR="\(.*\)"$/\1/p' "$BASE_DIR/.env")
  if [ -n "$old_base" ] && [ "$old_base" != "$BASE_DIR" ]; then
      log_info "Updating paths in .env: $old_base -> $BASE_DIR"
      sed -i "s#$old_base#$BASE_DIR#g" "$BASE_DIR/.env"
  fi
  touch "$LOCK_FILE"
  log_success "Files restored"

  set -a
  # shellcheck disable=SC1091
  source "$BASE_DIR/.env"
  set +a
  export GITEA_URL=${GITEA_URL:-"$GITEA_PROTOCOL://git.$DOMAIN"}

  log_section "Starting Services"
  while read -r file <&3; do
      [ -f "$file" ] || continue
      log_subsection "$(basename "$file" .yaml)"
      docker compose -f "$file" up -d
      # Competitor images are pulled from Gitea's registry, it must be up before them
      [ "$(basename "$file")" = "gitea.yaml" ] && wait_for_gitea
  done 3< <(compose_files)

  echo ""
  log_success "Restore complete! 🎉"

}

competition.sh_clean_command() {

  if [[ ${args[--no-backup]} ]]; then
      clean_environment false
  else
      clean_environment true
  fi

}

parse_requirements() {
  local key

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in
      --version)
        version_command
        exit
        ;;

      --help | -h)
        long_usage=yes
        competition.sh_usage
        exit
        ;;

      --verbose | -v)

        args['--verbose']=1
        shift
        ;;

      *)
        break
        ;;

    esac
  done

  action=${1:-}

  case $action in
    -*) ;;

    setup)
      action="setup"
      shift
      competition.sh_setup_parse_requirements "$@"
      shift $#
      ;;

    init)
      action="init"
      shift
      competition.sh_init_parse_requirements "$@"
      shift $#
      ;;

    start)
      action="start"
      shift
      competition.sh_start_parse_requirements "$@"
      shift $#
      ;;

    stop)
      action="stop"
      shift
      competition.sh_stop_parse_requirements "$@"
      shift $#
      ;;

    recreate)
      action="recreate"
      shift
      competition.sh_recreate_parse_requirements "$@"
      shift $#
      ;;

    import-frameworks)
      action="import-frameworks"
      shift
      competition.sh_import_frameworks_parse_requirements "$@"
      shift $#
      ;;

    backup)
      action="backup"
      shift
      competition.sh_backup_parse_requirements "$@"
      shift $#
      ;;

    restore)
      action="restore"
      shift
      competition.sh_restore_parse_requirements "$@"
      shift $#
      ;;

    clean)
      action="clean"
      shift
      competition.sh_clean_parse_requirements "$@"
      shift $#
      ;;

    "")
      competition.sh_usage >&2
      exit 1
      ;;

    *)
      printf "invalid command: %s\n" "$action" >&2
      exit 1
      ;;

  esac

  while [[ $# -gt 0 ]]; do
    key="$1"
    case "$key" in

      --)
        shift
        while [[ $# -gt 0 ]]; do
          key="$1"

          printf "invalid argument: %s\n" "$key" >&2
          exit 1

        done
        break
        ;;

      -?*)
        printf "invalid option: %s\n" "$key" >&2
        exit 1
        ;;

      *)

        printf "invalid argument: %s\n" "$key" >&2
        exit 1

        ;;

    esac
  done

}

