before_hook() {
  # Runs after argument parsing and filters, before any command

  if [[ ${args[--verbose]} ]]; then
      export VERBOSE=true
      export REDIRECT=/dev/stdout
  fi

}

initialize() {
  declare -g version="2.0.0"
  set -e

  # Runs before argument parsing, for every command (including --help)

  # .env holds the values computed by init (domain, credentials, tokens...)
  BASE_DIR=$(cd "$(dirname "$(realpath "${BASH_SOURCE[0]}")")" && pwd)
  if [ -f "$BASE_DIR/.env" ]; then
      set -a
      # shellcheck disable=SC1091
      source "$BASE_DIR/.env"
      set +a
  fi

  # Paths are always derived from the script location, never from .env or the current directory
  export BASE_DIR
  export CONFIG_DIR=$BASE_DIR/config
  export DOCKER_DIR=$BASE_DIR/docker
  export DATA_DIR=$BASE_DIR/data
  export BACKUP_DIR=$BASE_DIR/backups
  export LOCK_FILE=$BASE_DIR/competition.lock
  # Generated files
  export DYNAMIC_DOCKER_DIR=$BASE_DIR/dynamic/docker
  export DYNAMIC_FRAMEWORKS_DIR=$BASE_DIR/dynamic/frameworks

  export COMPOSE_PROJECT_NAME="competition_scripts"
  export COMPOSE_IGNORE_ORPHANS=true

  if [ -n "$DOMAIN" ]; then
      export GITEA_URL=${GITEA_URL:-"$GITEA_PROTOCOL://git.$DOMAIN"}
  fi

  export VERBOSE=false
  export REDIRECT=/dev/null

}

run() {

  declare -g long_usage=''
  declare -g -A args=()
  declare -g -A deps=()
  declare -g -a env_var_names=()
  declare -g -a input=()

  normalize_input "$@"
  parse_requirements "${input[@]}"
  before_hook

  case "$action" in
    "setup") competition.sh_setup_command ;;
    "init") competition.sh_init_command ;;
    "start") competition.sh_start_command ;;
    "stop") competition.sh_stop_command ;;
    "recreate") competition.sh_recreate_command ;;
    "import-frameworks") competition.sh_import_frameworks_command ;;
    "backup") competition.sh_backup_command ;;
    "restore") competition.sh_restore_command ;;
    "clean") competition.sh_clean_command ;;
  esac
}

start() {
  command_line_args=("$@")
  initialize
  run "${command_line_args[@]}"
}

start "$@"
